use std::{collections::HashMap,env,fs,io::{self,Write},process};use caveat_runtime::{ast::{Program,Statement},eval::{self,EventKind},parser,Attention,NodeId,NodeKind,Relation};
fn label(nodes:&HashMap<NodeId,NodeKind>,id:NodeId)->String{match nodes.get(&id){Some(NodeKind::Claim{proposition})=>proposition.clone(),Some(NodeKind::Evidence{description,source})=>format!("{description} [{source}]"),Some(NodeKind::Caveat{description,..})=>description.clone(),Some(NodeKind::Commitment{action,..})=>action.clone(),_=>format!("node#{id}")}}
fn main(){let mut interactive=false;let mut path=None;for a in env::args().skip(1){if a=="--interactive"||a=="-i"{interactive=true}else{path=Some(a)}}let path=path.unwrap_or_else(||{eprintln!("usage: caveat [--interactive] <file.cav>");process::exit(2)});let source=fs::read_to_string(&path).unwrap_or_else(|e|{eprintln!("caveat: {e}");process::exit(1)});let mut p=parser::parse(&source).unwrap_or_else(|e|{eprintln!("parse error: {e}");process::exit(1)});
if interactive{let indices:Vec<usize>=p.statements.iter().enumerate().filter_map(|(i,s)|matches!(s,Statement::Select{..}).then_some(i)).collect();for i in indices{let(choice,current)=match &p.statements[i]{Statement::Select{choice,option}=>(choice.clone(),option.clone()),_=>continue};let preview=eval::evaluate(&Program::new(p.statements[..i].to_vec())).unwrap_or_else(|e|{eprintln!("evaluation error before choice: {e}");process::exit(1)});let cp=preview.choices.get(&choice).unwrap();println!("\n=== {choice} ===");if let Some(b)=&preview.resources{println!("Attention: {} / {} remaining",b.remaining,b.initial)}println!("\nEvidence in play:");for e in preview.graph.nodes.iter().filter_map(|(id,n)|if matches!(n,NodeKind::Evidence{..}){Some((*id,n))}else{None}){let(id,n)=e;if let NodeKind::Evidence{description,source}=n{let effects:Vec<String>=preview.graph.edges.iter().filter(|x|x.from==id&&matches!(x.relation,Relation::Supports|Relation::Opposes)).map(|x|format!("{:?} {}",x.relation,label(&preview.graph.nodes,x.to))).collect();println!("  {description} [{source}]{}",if effects.is_empty(){String::new()}else{format!(" -> {}",effects.join(", "))});}}
println!("\nUnresolved caveats:");let mut any=false;for(id,n)in&preview.graph.nodes{if let NodeKind::Caveat{description,consequence,attention}=n{if *attention!=Attention::Examined{any=true;let targets:Vec<String>=preview.graph.edges.iter().filter(|x|x.from==*id&&x.relation==Relation::Qualifies).map(|x|label(&preview.graph.nodes,x.to)).collect();println!("  {description} [{consequence:?}, {attention:?}]{}",if targets.is_empty(){String::new()}else{format!(" -> qualifies {}",targets.join(", "))});}}}if !any{println!("  none")}
let reopened:Vec<String>=preview.history.iter().filter_map(|e|match &e.kind{EventKind::Reopened{commitment,..}=>Some(label(&preview.graph.nodes,*commitment)),_=>None}).collect();if !reopened.is_empty(){println!("\nReopened decisions: {}",reopened.join(", "))}if !cp.retaining.is_empty(){println!("\nChoosing now preserves {} unresolved item(s) in the decision record.",cp.retaining.len())}println!("\nOptions: {}",cp.options.join(" / "));let picked=loop{print!("> ");io::stdout().flush().unwrap();let mut input=String::new();io::stdin().read_line(&mut input).unwrap();let pick=input.trim().to_lowercase();if cp.options.contains(&pick){break pick}if input.is_empty(){break current.clone()}println!("Choose one of: {}",cp.options.join(", "));};if let Statement::Select{option,..}=&mut p.statements[i]{*option=picked;}}}
let r=eval::evaluate(&p).unwrap_or_else(|e|{eprintln!("evaluation error: {e}");process::exit(1)});println!("\nCAVEAT complete: {} nodes, {} edges, {} history events",r.graph.nodes.len(),r.graph.edges.len(),r.history.len());for(name,id)in&r.symbols{if let Some(NodeKind::Commitment{open,stop_reason,..})=r.graph.nodes.get(id){println!("decision {name}: {} ({stop_reason:?})",if *open{"REOPENED"}else{"committed"})}}}
